	Blanks off	String asis	TITLE 'Apple IIGS Window Manager                   DOCDEF.ASM';;          Copyright Apple Computer, Inc. 1986;          All rights reserved;          Written by Dan Oliver;;        This module contains the window definition procedure;        of a standard square cornered window.  The window can;        have, title bar with a close and/or zoom box, information;        bar, vertical scroll bar, horizontal scroll bar drop shadow,;        grow box or just a frame.;;; Files needed:;          DOCDEF.ASM;            DEF.MACROS;          DOCCALL.ASM;          ALERTDEF.ASM;          DEFUTIL.ASM;          DDATA.ASM;; Change history:;; 07/18/88  Dan O.	Changed hSetTitle to draw info bar in addition to the title bar because versions;	of the Window Manager on System Disks 3.1 and before redrew the entire frame;	when the title changed.  The application "List Plus" depended on the info bar;	being redrawn when the title was changed.;; 08/08/88  Dan O.	I had (a while ago) removed masking the scroll bar thumb position in TaskScroll;	with the window's origin mask.  I've now put that back in.  This means that;	sometimes the thumb may not go all the way to the right side (horizontal scroll;	bars).;; 10/28/88  Dan O.	Close window free's title and color table if they're a handle.;	DefProcs also handle titles and color tables as pointers or handles.;	Change set title and color table to dispose of exsisting handles first.;; 21 May 89	Steven Glass;; Minor change to new origin to prevent the orphaning of regions during; scrolling.;; 27-Sep-90	Dave Lyons;; Changes to use Get640Colors instead of hard-coding our own solid-color; table.;; 14-Nov-90	Dave Lyons;; Fixed memory-trashing bug in unlockColor (the two words of the color table handle; were reversed, so we were turning off bit 15 of a semi-random location).; See separate fix in WCtlDef.asm's own unlockColor subroutine.; (This bug means that Window Color Table Resources can't be used reliably in; System 5.0 through 5.0.3.);	INCLUDE 'ALL.MACROS'	include 'WindMgrEquates.asm';; --- DefProc direct page offsets ----------------------------;windColors	equ 1	Pointer to window's color table.w_wrect	equ windColors+4	Bounds of window's strucRgn.w_rect	equ w_wrect+8	General RECT area.w_work	equ w_rect+8	w_work space.DIRECTSIZE	equ w_work+37	Size of allocated direct page.saveDpage	equ DIRECTSIZE+1	Caller's direct page.returnAddr	equ saveDpage+2	Long return addresses.w_param	equ returnAddr+3	Parameter defined by defProc operation.w_wind	equ w_param+4	Pointer to window record.operation	equ w_wind+4	DefProc operation to perform.globals	equ operation+2	Pointer to Window Manager globals.result	equ globals+4	Result defined by defProc operation.;;;; --- wCallDefProc parameter list offsets --------------------;dRequest	equ 0defProcID	equ dRequest+2newParam	equ defProcID+2;;; --- Document window record offsets -------------------------;wtitle	equ 212	212 Pointer to window's title.wtitle_w	equ wtitle+4	216 Width of title in pixels.worgn_mask	equ wtitle_w+2	218 Mask for horizontal origin.wfull	equ worgn_mask+2	220 Size of window,	used with ZoomWindow.wcolor	equ wfull+8	228 Pointer to window's color table.y_origin	equ wcolor+4	232 Content's vertical offset.x_origin	equ y_origin+2	234 Content's horizontal offset.data_h	equ x_origin+2	236 Height of total	data area.data_w	equ data_h+2	238 Width of total data area.wmaxheight	equ data_w+2	240 Maximum height for grow window.wmaxwidth	equ wmaxheight+2	242 Maximum width for grow window.vscroll	equ wmaxwidth+2	244 Amount to scroll vertically (arrows).hscroll	equ vscroll+2	246 Amount to scroll horizonally (arrows).vpage	equ hscroll+2	248 Amount to page vertically (page region).hpage	equ vpage+2	250 Amount to page horizontally (page rgn).wInfoRef	equ hpage+2	252 Value passed to	Draw Info routine.wInfoHeight	equ wInfoRef+4	256 Height of information bar.woldYOrg	equ wInfoHeight+2	258 Save y origin on full window.woldXOrg	equ woldYOrg+2	260 Save x origin on full window.wInfoDraw	equ woldXOrg+2	262 Address of routine to draw Info Bar.DOCSIZE	equ wInfoDraw+4	266 Size of document window record.;;; --- New window parameter list offsets	----------------------------;p_length	equ 0	Number of bytes in parameter list.p_wframe	equ p_length+2	Type of window, frame flags.p_wtitle	equ p_wframe+2	Pointer to window's title.p_wrefCon	equ p_wtitle+4	Reserved for application.p_wfull	equ p_wrefCon+4	Size of window, used with ZoomWindow.p_wcolor	equ p_wfull+8	Pointer to window's color table.p_y_origin	equ p_wcolor+4	Content's vertical offset.p_x_origin	equ p_y_origin+2	Content's horizontal offset.p_data_h	equ p_x_origin+2	Height of total data area.p_data_w	equ p_data_h+2	Width of total data	area.p_wmaxheight	equ p_data_w+2p_wmaxwidth	equ p_wmaxheight+2p_vscroll	equ p_wmaxwidth+2	Amount to scroll vertically (arrows).p_hscroll	equ p_vscroll+2	Amount to scroll horizonally (arrows).p_vpage	equ p_hscroll+2	Amount to page vertically (page region).p_hpage	equ p_vpage+2	Amount to page horizontally (page rgn).p_wInfoText	equ p_hpage+2p_wInfoH	equ p_wInfoText+4	Height of infomation bar.p_wdefProc	equ p_wInfoH+2	NOT USED.p_wInfoDraw	equ p_wdefProc+4	Address of routine to draw Info Bar.p_updateDraw	equ p_wInfoDraw+4	Address of routine to draw content region.p_position	equ p_updateDraw+4p_behind	equ p_position+8p_windrec	equ p_behind+4p_size	equ p_windrec+4;;; --- Window DefProc frame offsets -----------------------------;TITLEH	equ 13	Height of title bar.TITLEL	equ 2	Space on left and right of title bar pattern.TITLET	equ 3	Space on top and bottom of title bar pattern.;CLOSEL	equ 10	Left side of window	to left side of close box.CLOSET	equ 2	Top of window to top of close box.CLOSEW	equ 22	Width of close box.CLOSEH	equ 11	Height of close box.;;; --- Window color table offsets -----------------------------;FRAME_CLR	equ 0	Frame's outline.TITLE_CLR	equ FRAME_CLR+2	Title's color.BAR_CLR	equ TITLE_CLR+2	Title bar's initerior.GROW_CLR	equ BAR_CLR+2	Grow box interior.INFOR_CLR	equ GROW_CLR+2	Information bar interior.COLORSIZ	equ INFOR_CLR+2	Size of color table.;;; --- Offsets into GrafPort;boundsRect	EQU   $08  ; Rect - LocInfo - BoundsRectclipRgn	EQU   $18  ; RgnHandle - GrafPort - Clip Rgn. PointervisRgn	EQU   $1C  ; RgnHandle - GrafPort - Vis. Rgn. Pointer;;; --- Part codes for standard controls -----------------;;titlePart	equ 16closePart	equ 17zoomPart	equ 18infoPart	equ 19;;; --- IDs of window	frame controls ---------------------------;titleBarID	equ 0infoBarID	equ 2VScrollID	equ 4HScrollID	equ 6GrowID	equ 8;;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT Allocate	IMPORT Bring	IMPORT Convert	IMPORT Current	IMPORT Draw	IMPORT Expand	IMPORT Get	IMPORT Have	IMPORT Make	IMPORT Redraw	IMPORT Restore	IMPORT Save	IMPORT Set	IMPORT Window***	IMPORT colorBlack	IMPORT infoBarDefProc	IMPORT longCall	IMPORT pushDpage	IMPORT setTheOrigin	IMPORT titleBarDefProc	IMPORT zeroOrigin;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY pushWindTitle	ENTRY unlockTitle	ENTRY TaskScroll	ENTRY ckZoom	ENTRY ck_origin	ENTRY cloneRect	ENTRY docBehind	ENTRY docCallDefProc	ENTRY docPosition	ENTRY docRecSize	ENTRY docDispose	ENTRY endFrameDraw	ENTRY findCtlHand	ENTRY frameRect	ENTRY getDeskBounds	ENTRY getGlobalRect	ENTRY getLineSize	ENTRY getLocalRect	ENTRY getLong	ENTRY getRgnBounds	ENTRY hDrawInfo	ENTRY hEndInfoDraw	ENTRY hGetColorTable	ENTRY hGetDataSize	ENTRY hGetFrameFlag	ENTRY hGetInfoDraw	ENTRY hGetInfoRect	ENTRY hGetInfoRefCon	ENTRY hGetMaxGrow	ENTRY hGetOrgMask	ENTRY hGetOrigin	ENTRY hGetPage	ENTRY hGetScroll	ENTRY hGetTitle	ENTRY hGetZoomRect	ENTRY hNewSize	ENTRY hSetColorTable	ENTRY hSetDataSize	ENTRY hSetFrameFlag	ENTRY hSetInfoDraw	ENTRY hSetInfoRefCon	ENTRY hSetMaxGrow	ENTRY hSetOrgMask	ENTRY hSetOrigin	ENTRY hSetPage	ENTRY hSetScroll	ENTRY hSetTitle	ENTRY hSetZoomRect	ENTRY hStartDrawing	ENTRY hStartInfoDraw	ENTRY hStartMove	ENTRY hTask	ENTRY hZoomWindow	ENTRY makeRectLocal	ENTRY new_origin	ENTRY pushLineSize	ENTRY pushParam	ENTRY pushPort	ENTRY pushWindLong	ENTRY pushrect	ENTRY pushwrect	ENTRY saveWOrigin	ENTRY saveWRect	ENTRY setDefFull	ENTRY setLong	ENTRY setTitleWidth	ENTRY setWindField	ENTRY setcolorptr	ENTRY unlockColor	ENTRY setoutline	ENTRY shutdown	ENTRY startFrameDraw	ENTRY startup	ENTRY swap_origin	ENTRY swap_word	ENTRY zeroDesRect;;;====================================================;          Standard	document window defProc.;====================================================;;   IN:    PUSH:LONG - space for result.;          PUSH:LONG - pointer to Window Manager globals.;          PUSH:WORD - operation to perform.;          PUSH:LONG - pointer to window's port.;          PUSH:LONG - addtional parameter defined by operation.;          JSL to defProc.;;  OUT:    result =	result from operation.;          Carry clear if no error.;          Carry set if error, Y = error code.;	EXPORT docDefProcdocDefProc	PROC;;; --- Set up for defProc call --------------------------------;	jsr startup;;; --- Dispatch to operation handler --------------------------;	lda <operation	cmp #11	Operation out of range?	bcs skip1;	asl a	tax	jsr (taskTable,x)	sta <result	x/a = result.	stx <result+2	y = error code if carry set.	bcs skip1	ldy #0	No error code.;;; --- Return to caller ---------------------------------------;skip1	brl shutdown;;taskTable	DC.W docDraw	0  Draw window frame.	DC.W docHit	1  Hit test window.	DC.W docRgns	2  Compute struc and content regions.	DC.W docInit	3  Additional initailization.	DC.W docDispose	4  Additional diaposal.	DC.W docDrag	5  Return address of draw frame routine.	DC.W docGrow	6  Draw grow window	outline.	DC.W docRecSize	7  Return window record size.	DC.W docPosition	8  Return position and size of window.	DC.W docBehind	9  Return where window goes in list.	DC.W docCallDefProc	10 Generic call to defProc.;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 0        Draw document window's frame.;100= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    <w_wind = window to draw.;          <w_param =	part to draw, 0=entire, 1=close, 2=zoom, 3=info.;          <w_param+2	= bit 15 = 1 to hilite.;;  OUT:    x/a = result.;docDraw	lda <w_param	Dispatch to part to	draw.	asl a	tax	jmp (drawParts,x);drawParts	DC.W drawWhole,drawClose,drawZoom,drawInfo;;;--------------------------------------------;          Draw entire window frame.;110-----------------------------------------;drawWhole	jsr setcolorptr	Set window's color table pointer.;	ldy #FRAME_CLR	jsr setoutline	Set pen color and pattern.;	jsr getLocalRect	<w_wrect = frame RECT	in local.;	                  <w_rect = frame RECT in	local.;	jsr pushLineSize	_SetPenSize;	jsr frameRect	Draw outline around	frame.;	ldy #wFrameCtls+1	Does the window have any frame controls?	lda [<w_wind],y	beq exit110;	jsr pushPort	Pass port that has frame controls.	_DrawControls;exit110	jsr unlockColor	Leave color table unlocked.	clc	No error flag.	rts;;;--------------------------------------------;          Draw close box.;120-----------------------------------------;;   IN:    <w_param+2	= negative to hilite.;drawClose	lda #closePart	Hilite close box, just in case.;enter120	ldx <w_param+2	Hilite?	bmi store120	lda #0	Unhilite.store120	sta <w_param+2	Part to hilite.;	lda #titleBarID	Find title bar control.	jsr findCtlHand	bcs exit120;	pei <w_param+2	Pass part to hilite	or unhilite.	phx	Pass handle of control.	pha	_HiliteControl	Draw the part.;exit120	clc	rts;;;--------------------------------------------;          Draw zoom box.;130-----------------------------------------;;   IN:    <w_param+2	= negative to hilite.;drawZoom	lda #zoomPart	Hilite zoom box.	bra enter120;;;--------------------------------------------;          Draw info bar.;140-----------------------------------------;drawInfo		; 	clc	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =; 1        Test hit	on a standard documnet window.;200= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    w_param = y point to check, local to window frame.;          w_param+2 = x point to check, local to window frame.;          yrat = y	global point to check.;          xrat = x	global point to check.;          w_param = y local point to check.;          w_param+2 = x local point to check.;;  OUT:    a = part	point is zero if no	point found,;              else	a = wInContent;	    wInDrag;	    wInGrow;	    wInGoAway;	    wInZoom;	    wInInfo;	    wInFrame;docHit		; ;foundCtl	equ w_work;	lda #wInFrame	If no controls, on frame, just in case.	ldy #wFrameCtls+1	Does the window have any frame controls?	lda [<w_wind],y	beq exit;	jsr pushParam	Pass pointer to point to check.	_LocalToGlobal	Convert point to check to global.;	pha	Space for result.	lda #foundCtl	Pass place to store	handle of control.	jsr pushDpage	pei <w_param+2	Pass x point to check (global).	pei <w_param	Pass y point to check (global).	pha	Pass pointer to window.	pha	_GetPort	Current port is port to check.	_FindControl	lda #wInFrame	Not on control, just in case.	plx	Control found?	beq exit;	lda #wInGoAway	cpx #closePart	In close box part?	beq exit;	lda #wInZoom	cpx #zoomPart	In zoom box part?	beq exit;	pha	Space for result.	pha	pei <foundCtl+2	Pass handle of found control.	pei <foundCtl	_GetCtlRefCon	pla	plx	Get control's ID.	lda >hitCodes,x	Fetch code to return.	cmp #wInDrag	Special case wInDrag.	bne exit;	ldy #wFrame	Is window moveable?	lda [<w_wind],y	and #F_MOVE	bne okMove	lda #wInFrame	Window is not moveable.	bra exit;okMove	lda #wInDrag	Window is moveable.;exit	clc	No error.	rts;hitCodes	DC.W wInDrag,wInInfo,wInFrame,wInFrame,wInGrow;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =; 3        Perform additional initialization.;400= = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    w_wrect = content area in global coordinates.;          w_param = pointer to NewWindow	parameter list:;	   WORD - window frame type:;	                  $8000 - title bar.;	                  $4000 - close box.;	                  $1000 - right scroll bar.;	                  $0800 - bottom scroll	bar.;	                  $0400 - sizer box.;	                  $0100 - full box.;	                  $0080 - allow move on	title bar.;	                  $0020 - visible.;	   LONG - pointer to window's title (first byte = length).;	   LONG - reference	value, application reserved.;	   RECT - full rect	for content, zero for default.;	   LONG - pointer to color window's table.;	   WORD - vertical offset of content region.;	   WORD - horizontal offset of content region.;	   WORD - height of	total data area.;	   WORD - width of total data area.;	   WORD - maximum height of content allowed in grow window.;	   WORD - maximum width of content allowed in grow window.;	   WORD - pixels to	scroll vertically for arrows.;	   WORD - pixels to	scroll horizontally	for arrows.;	   WORD - pixels to	scroll vertically for page region.;	   WORD - pixels to	scroll horizontally	for page region.;	   LONG - value passed to draw Information bar routine.;	   WORD - height of	information bar.;	   LONG - address of window's definition procedure.;	   LONG - address of routine that will draw on Info. Bar.;	   LONG - address of routine that will draw content region.;	   RECT - the position and size of content area.;	   LONG - poistion window goes in window list.;	   LONG - address of window record, zero to allocate.;;  OUT:    Carry clear if window created if no error.;          Carry set if error, y = error code.;docInit		; ;;; --- Transferr data from parameter list to window record ----;; wFrame, wTitle, wRefCon, wZoom, wColor, wYOrigin, wXorigin, wDataH, wDataW,; wMaxH, wMaxW, wScrollVer, wScrollHor,	wPageVer, wPageHor,	wInfoRefCon,; wInfoHeight, wFrameDefProc, wInfoDefProc.;	ldy #wframe	Place in record to put parameter list.	ldx #p_wframelop2	phy	txy	lda [<w_param],y	ply	ora [<w_wind],y	OR to not disturb wFrame bits already set.	sta [<w_wind],y	iny	iny	inx	inx	cpx #p_updateDraw	bne lop2;;	ldy #wOrgn_mask	Set the wOrgn_mask field.	lda #$FFFF	Set horizontal origin mask to single	sta [<w_wind],y	pixel resolution.;	ldy #p_wRefCon	Set the wRefCon field.	ldx #wRefCon+2	jsr setWindField;	ldy #p_updateDraw	Set the wContDraw field.	ldx #wContDraw+2	jsr setWindField;;; --- Make sure that the data sizes are	in range -------------;	ldy #data_h	Force data size to be in bounds.	lda [<w_wind],y	and #$3FFF	sta [<w_wind],y	iny	iny	lda [<w_wind],y	and #$3FFF	sta [<w_wind],y;;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = =; 2        Initialize window's StructRgn and ContentRgn.;400= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = =;;   IN:    w_wind = window pointer.;;  OUT:    w_rect = trashed.;          w_wrect = trashed.;growHeight	equ w_work	Local direct page use.growWidth	equ growHeight+2frame	equ growWidth+2portPtr	equ frame+2temp	equ portPtr+4contentH	equ temp+4contentW	equ contentH+2;;docRgns	jsr getGlobalRect	w_wrect = port bounds.	jsr cloneRect	Clone 'w_wrect' into 'w_rect'.;;;----------------------------------------------;          Set size	of content region.;----------------------------------------------;	lda <w_rect+y2	Compute and save content height.	sec	sbc <w_rect+y1	sta <contentH;	lda <w_rect+x2	Compute and save content width.	sec	sbc <w_rect+x1	sta <contentW;	ldy #wcontRgn+2	Pass handle of content region.	jsr pushWindLong	jsr pushrect	_RectRgn;;;----------------------------------------------------------------------;          Compute size of frame by expanding the content area.;----------------------------------------------------------------------;;; ------ Get size of grow box --------------------------------;	ldy #wframe	lda [<w_wind],y	sta <frame	Save wFrame.	and #F_RSCRL+F_BSCRL+F_GROW Any controls that need grow?	beq skip404	Don't call GrowSize if none.;	pha	Space for result	pha	_GrowSize	Get the size of the	grow box.	pla	sta <growHeight	pla	sta <growWidth;;; ------ Expand width of frame outline -----------------------;skip404	jsr pushrect	Pass RECT of entire	window.	ldy #lineW	Pass width of vertical line negated.	lda [<globals],y	eor #$FFFF	inc a	pha	pea $FFFF	Pass height of horizontal line negated.	_InsetRect	Expand window RECT by width of frame.;;; ------ Add title bar ---------------------------------------;	lda <frame	Save wFrame.	bpl skip400	Title bar?;	ldy #titleHeight	lda <w_rect+y1	sec	sbc [<globals],y	inc a	Share top line.	sta <w_rect+y1;;; ------ Add info bar ----------------------------------------;skip400	lda <frame	and #F_INFO	Information bar?	beq skip401;	lda <w_rect+y1	ldy #wInfoHeight	sec	sbc [<w_wind],y	Raise top side for information bar.	inc a	Share top line.	sta <w_rect+y1;;; ------ Add vertical scroll bar -----------------------------;skip401	lda <frame	and #F_RSCRL	Right scroll bar?	beq skip402;	lda <w_rect+x2	clc	adc <growWidth	Expand right side for vertical scroll.;	ldy #lineW	sec	sbc [<globals],y	sta <w_rect+x2;;; ------ Add horizontal scroll bar ---------------------------;skip402	lda <frame	and #F_BSCRL	Bottom scroll bar?	beq skip403;	lda <w_rect+y2	clc	adc <growHeight	Expand bottom side for bottom scroll.	dec a	sta <w_rect+y2;;; --- Set size of window's strucRgn --------------------------;skip403	ldy #wstrucRgn+2	Pass handle of StructRgn.	jsr pushWindLong	jsr pushrect	Set to global RECT in 'w_rect'.	_RectRgn;;;------------------------------------------------------;          Create any needed frame controls.;------------------------------------------------------;;   <w_rect = frame's rect, in global.;   <w_wrect = content rect, in global.;	pha	Space for result.	pha	_GetPort	pla	sta <portPtr	Save pointer to current port.	pla	sta <portPtr+2;	lda <frame	and #F_RSCRL+F_BSCRL+F_GROW+F_TITLE+F_INFO	bne ok403	brl setDefFull	If no controls, skip kill and create.;ok403	pei <portPtr+2	Pass port to kill controls in.	pei <portPtr	_KillControls;;;-------------------------------------------;          Create frame controls.;-------------------------------------------;; --- Convert bounds to local --------------------------------;	jsr makeRectLocal	<w_wrect = local, <w_rect = <w_wrect clone.;;          <w_wrect =	bounds of window structure in local.;          <w_rect = bounds of window structure in local.;; --- Create title bar control -------------------------------;	lda <frame	Is there a title bar?	and #F_TITLE	bne ok404;	inc <w_rect+y1	Special case no title bar so info bar	bra makeInfo	and vertical scroll	bar can share lines.;ok404	ldy #titleHeight	Compute bounds of title bar.	lda [<globals],y	sta <w_rect+y2;	jsr setTitleWidth	Set the width of the new title.;	pha	Space for result.	pha	pei <portPtr+2	Pass window owner.	pei <portPtr	jsr pushRect	Pass address of bounds RECT.	pei <w_wind+2	Pass ctlData.	pei <w_wind	lda <frame	Pass flags.	and #F_CLOSE+F_ZOOM	xba	pha	pha	Pass value (not used, set by control).	pha	Pass param1 (not used).	pha	Pass param2 (not used).	pea titleBarDefProc>>16 Pass address of	control defProc.	pea titleBarDefProc	pea titleBarID	Pass refCon.	pha	Low word not used.	pha	Pass color table (not used).	pha	_NewControl	pla	Don't need returned handle.	pla;	lda <w_rect+y2	Subtract title bar from frame RECT.	sta <w_rect+y1	lda <w_wrect+y2	sta <w_rect+y2;;; --- Create info bar control --------------------------------;makeInfo	lda <frame	Is there a info bar?	and #F_INFO	beq makeVScroll;	dec <w_rect+y1	Share top line with	bottom of title.;	ldy #wInfoHeight	Compute bounds of info bar.	lda [<w_wind],y	clc	adc <w_rect+y1	sta <w_rect+y2;	pha	Space for result.	pha	pei <portPtr+2	Pass window owner.	pei <portPtr	jsr pushRect	Pass address of bounds RECT.	pei <w_wind+2	Pass ctlData.	pei <w_wind	lda #0	Common need.	pha	Pass flags.	pha	Pass value.	pha	Pass param1 (not used).	pha	Pass param2 (not used).	pea infoBarDefProc>>16 Pass address of control defProc.	pea infoBarDefProc	pea infoBarID	Pass refCon.	pha	Low word not used.	pha	Pass color table (not used).	pha	_NewControl	pla	Don't need returned handle.	pla;	lda <w_rect+y2	Subtract info bar from frame RECT.	sta <w_rect+y1	lda <w_wrect+y2	sta <w_rect+y2;;; --- Create vertical scroll bar -----------------------------;makeVScroll	lda <frame	Is there a vertical	scroll bar?	and #F_RSCRL	beq makeGrow;	dec <w_rect+y1	Share top side.	lda <w_rect+x2	Compute bounds of info bar.	sec	sbc <growWidth	sta <w_rect+x1;	lda <frame	If no grow box or horizontal scroll	and #F_BSCRL+F_GROW	bar than go to bottom of window.	beq ok401;	lda <w_rect+y2	Pull bottom of vertical scroll bar up	sec	to make room for grow box and/or	sbc <growHeight	horizontal scroll bar.	inc a	sta <w_rect+y2;ok401	pha	Space for result.	pha	pei <portPtr+2	Pass window owner.	pei <portPtr	jsr pushRect	Pass address of bounds RECT.	pha	Pass title (not used).	pha	pea $0003	Pass flags.	ldy #y_origin	Pass value.	lda [<w_wind],y	pha	pei <contentH	Pass view height in	param1.	ldy #data_h	Pass data height in	param2.	lda [<w_wind],y	pha	lda #0	Common need.	pea $0600	Pass defProc for scroll bar.	pha	pea VScrollID	Pass refCon (ID for	vertical bar).	pha	pha	Pass default color table.	pha	_NewControl	pla	Get handle of scroll bar.	plx	jsr setBarValue	Move scroll bar value into refCon;;; --- Create grow box control --------------------------------;makeGrow	lda <frame	Is there a grow box?	and #F_GROW	beq makeHScroll;	lda <w_wrect+x2	Compute bounds of grow box.	sta <w_rect+x2	sec	sbc <growWidth	sta <w_rect+x1	lda <w_wrect+y2	sta <w_rect+y2	sec	sbc <growHeight	sta <w_rect+y1;	pha	Space for result.	pha	pei <portPtr+2	Pass window owner.	pei <portPtr	jsr pushRect	Pass address of bounds RECT.	lda #0	Common need.	pha	Pass title (not used).	pha	pha	Pass flags.	pha	Pass value.	pha	Pass param1 (not used).	pha	Pass param2 (not used).	pea $0800	Pass defProc for grow box.	pha	pea GrowID	Pass refCon (ID for	grow box).	pha	pha	Pass default color table.	pha	_NewControl	pla	Don't need returned handle.	pla;;; --- Create horizontal scroll bar ---------------------------;makeHScroll	lda <frame	Is there a horizontal scroll bar?	and #F_BSCRL	beq setDefFull;	lda <w_wrect+y2	Compute bounds of horizontal scroll bar.	sta <w_rect+y2	sec	sbc <growHeight	sta <w_rect+y1;	lda <w_wrect+x1	sta <w_rect+x1	lda <w_wrect+x2	sta <w_rect+x2;	lda <frame	If no grow box or vertical scroll	and #F_RSCRL+F_GROW	bar than go to right side of window.	beq ok402;	lda <w_rect+x2	Pull right side of horizontal scroll	sec	bar in to make room	for grow box and/or	sbc <growWidth	vertical scroll bar.	ldy #lineW	clc	adc [<globals],y	sta <w_rect+x2;ok402	pha	Space for result.	pha	pei <portPtr+2	Pass window owner.	pei <portPtr	jsr pushRect	Pass address of bounds RECT.	pha	Pass title (not used).	pha	pea $001C	Pass flags.	ldy #x_origin	Pass value.	lda [<w_wind],y	pha	pei <contentW	Pass view height in	param1.	ldy #data_w	Pass data height in	param2.	lda [<w_wind],y	pha	lda #0	Common need.	pea $0600	Pass defProc for scroll bar.	pha	pea HScrollID	Pass refCon (ID for	horizontal bar).	pha	pha	Pass default color table.	pha	_NewControl	pla	Get handle of scroll bar.	plx	jsr setBarValue	Move scroll bar value into refCon;;; = = = = = = = = =	= = = = = = = = = =	= = = = = =;          Set default maximum grow size;          and full	size and position.;410= = = = = = = =	= = = = = = = = = =	= = = = = =;;   IN:    w_wind = pointer to window.;          w_wind[wmaxheight] = 0 to set default max grow height.;          w_wind[wmaxwidth]  = 0 to set default max grow width.;          w_wind[wfull+y2]   = 0 to set default full size and position.;;  OUT:    Values set if zero flags passed in record.;          w_rect = trash.;          w_wrect = trash.;	ENTRY setDefFullsetDefFull		;       ;	ldy #wstrucRgn	Get global coordinates of content.	jsr getRgnBounds	<w_wrect = wwStructRgn bounds.	jsr cloneRect	<w_rect = <w_wrect.;	ldy #wcontRgn	Get global coordinates of content.	jsr getRgnBounds	<w_wrect = content bounds.;	ldx #2lop410	lda <w_wrect+y2,x	Get width/height of	wcontRgn.	sec	sbc <w_wrect+y1,x	sta <w_wrect+y2,x	Store width/height in x2/y2.;	lda <w_rect+y2,x	Get width/height of	wstrucRgn,	sec	sbc <w_rect+y1,x	sbc <w_wrect+y2,x	less width/height of wcontRgn,	sta <w_rect+y2,x	equals window border width/height.;	lda <w_wrect+y1,x	Get left/top window	border,	sec	sbc <w_rect+y1,x	sta <w_rect+y1,x	and store in w_rect+x1/w_rect+y1.;	dex	dex	bpl lop410;	jsr getDeskBounds	<w_wrect = bounds of desktop.;	ldx #2lop411	lda <w_wrect+y2,x	sec	sbc <w_wrect+y1,x	Width/height of desktop,	sbc <w_rect+y2,x	less width/height of window border,	sta <w_rect+y2,x	equals max content width/height.	dex	dex	bpl lop411;;	ldy #wmaxheight	Does maximum grow height need setting?	lda [<w_wind],y	bne ok410;	lda <w_rect+y2	Set default max grow height.	sta [<w_wind],y;ok410	iny	iny	lda [<w_wind],y	Does maximum grow width need setting?	bne ok411;	lda <w_rect+x2	Set default max grow width.	sta [<w_wind],y;;; --- Set default full RECT ------------------------------------------;ok411	ldy #wfull+y2	lda [<w_wind],y	Does full RECT need	setting?	bne exit410;	lda <w_wrect+y1	Get desktop's top side,	clc	adc <w_rect+y1	plus window's top border,	ldy #wfull+y1	sta [<w_wind],y	equals full top side,	adc <w_rect+y2	plus max height,	ldy #wfull+y2	sta [<w_wind],y	equals full bottom side.;	lda <w_wrect+x1	Get desktop's left side,	clc	adc <w_rect+x1	plus window's left border,	ldy #wfull+x1	sta [<w_wind],y	equals full left side,	adc <w_rect+x2	plus max width,	ldy #wfull+x2	sta [<w_wind],y	equals full right side.;exit410	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;          Move scroll bar value into refCon.;420= = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   In:    x/a = handle of control.;;  OUT:    CtlRefCon field = CtlValue field.;          <temp = trash.;setBarValue	sta <temp	stx <temp+2;	ldy #2	Deference handle.	lda [<temp],y	tay	lda [<temp]	sta <temp	sty <temp+2;	ldy #CtlValue	Set control's refcon to its value.	lda [<temp],y	The refcon is used by TaskScroll	ldy #CtlrefCon	is call for dragged	thumber.  The	sta [<temp],y	refcon is the old position.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;          Move a long value from the;          parameter list into the window record.;430= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    w_param = pointer to parameter	list.;          w_wind = pointer to window record.;          y = index to LOW word of value in parameter list.;          x = index to HIGH word of value in window record.;	ENTRY setWindFieldsetWindField		;       ;	lda [<w_param],y	pha	iny	iny	lda [<w_param],y	txy	sta [<w_wind],y	dey	dey	pla	sta [<w_wind],y	rts;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;          Set width of title.;440= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    <w_wind = pointer to window.;          Pointer to title in wTitle field of window record.;;   OUT:   wTitle_w	field of window record = width of window.;	ENTRY setTitleWidthsetTitleWidth;	IMPORT pushWindTitle	IMPORT unlockTitle;	pha	Space for result.	jsr pushWindTitle	Pass pointer to title.	_StringWidth	pla	Set width of title in window record.	ldy #wTitle_w	sta [<w_wind],y;	brl unlockTitle	Leave title unlocked.;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 4        Draw grow outline of window.;500= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN: <w_wind = pointer to window to be closed.;;  OUT: x/a = NIL to continue close, else abort.;	ENTRY docDisposedocDispose	ldy #wtitle+2	Was the title allocated?	lda [<w_wind],y	bpl @skip1	jsr @dispose	Free title.;@skip1	ldy #wColor+2	Was the color table allocated?	lda [<w_wind],y	bpl @skip2	jsr @dispose	Free color table.@skip2	bra docDrag	Return NIL.;;;-------------------------------------------------------------------;	Dispose of handle in window record.;-------------------------------------------------------------------;@dispose	and #$7FFF	pha	dey	dey	lda [<w_wind],y	pha	_DisposeHandle	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = = =; 5        Return address of routine to	draw window outline.;510= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = = =;;  OUT:    x/a = result, zero for default outline.;docDrag		; ;	lda #0	Return FALSE to continue disposal.	tax	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 6        Draw grow window outline.;600= = = = = = = =	= = = = = = = = = =	= = = = =;;  OUT:    x/a = result.;docGrow		; ;	lda #0	Perform default action.	tax	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 7        Return window record size.;610= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    <w_param =	pointer to parameter table.;;  OUT:    a = additional bytes needed in window record.;	ENTRY docRecSizedocRecSize		;       ;	lda [<w_param]	Check length paramter.	cmp #p_size	Proper size?	beq ok610;	ldy #$0E01	Bad parameter list length error.	sec	Error flag.	rts;;ok610	ldy #p_windrec+1	Has a record already been allocated?	lda [<w_param],y	beq ok611	iny	lda [<w_param],y	Return pointer to record.	ora #$8000	Make negative to say record is allocated.	tax	dey	dey	lda [<w_param],y;-----------------------------------------------------------;; Zero the record provided;	phx	pha	phd	tsc	tcd	ldy #DOCSIZE-2	Get size of record.(this includes the window	lda #0	record header)@loop	sta [3],y	dey	dey	bpl @loop	sta [3]	In case it was not even;	pld	pla	plx;	clc	rts;ok611	lda #DOCSIZE-wtitle	Addtional bytes needed.	ldx #0	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 8        Return position and size of window.;620= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    w_param = pointer to parameter	table.;;  OUT:    x/a = pointer to RECT that is new window's position and size.;	ENTRY docPositiondocPosition		;       ;	ldx <w_param+2	Return pointer to RECT in w_param list.	lda <w_param	clc	adc #p_position	bcc exit620	inx;exit620	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 9        Return where window goes in list.;630= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    w_param = pointer to parameter	table.;;  OUT:    x/a = pointer to window this	window should be behind, or;                $00000000 if this window should be bottom most, or;                $FFFFFFFF if this window should be top most.;	ENTRY docBehinddocBehind		;       ;	ldy #p_behind+2	Return value in parameter list.	lda [<w_param],y	tax	dey	dey	lda [<w_param],y;	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;        Get zoom box's coordinates.;750= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    w_wind = window to check.;          w_wrect = window's coordinates, local to window.;;  OUT:    w_rect = zoom box's coordinates.;	ENTRY getzoomcorgetzoomcor		;       ;	lda <w_wrect+x2	sec	sbc #CLOSEL	sta <w_rect+x2	sec	ldy #closeWidth	sbc [<globals],y	Less width of icon font.	sta <w_rect+x1;	bra top_bottom	Compute top and bottom.;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;        Get close box's coordinates.;760= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:  w_wind = pointer to window.;;  OUT:  w_rect = close box's coordinates.;	ENTRY getclosecorgetclosecor		;       ;	lda #CLOSEL	sta <w_rect+x1	clc	ldy #closeWidth	adc [<globals],y	Add width of icon font.	sta <w_rect+x2;top_bottom	lda #CLOSET	sta <w_rect+y1	clc	ldy #closeHeight	adc [<globals],y	Add height of icon font.	sta <w_rect+y2;	rts;	ENDP;;            APPEND	DOCCALL.ASM	TITLE 'Apple IIGS Window Manager                   DOCCALL.ASM';;          Copyright Apple Computer, Inc. 1986;          All rights reserved;          Written by Dan Oliver;;;;============================================; 10       Generic call to defProc.;============================================;;   IN:    <w_wind = pointer to window record.;          <globals	= pointer to Window	Manager globals.;          <w_param =	pointer to parameter table:;	   dRequest   WORD	operation.;	   defProcID  WORD	0 for this defProc.;	   newParam   LONG	possible new value to set.;;  OUT:    x/a = result.;docCallDefProc	PROC;	ldy #defProcID	Is this a call to me?	lda [<w_param],y	bne exit1;	lda [<w_param]	Get special operation number.	cmp #34	In range?	bcs exit1;	asl a	tax	lda >specialOps,x	pha;	ldy #newParam+2	lda [<w_param],y	tax	Pass high word of newParam in X.	dey	Pass y = to newParam offset.	dey	lda [<w_param],y	Pass low word of newParam in A.exit1	rts	Go to special op handler.;;specialOps	DC.W hSetOrgMask-1	0	DC.W hSetMaxGrow-1	1	DC.W hSetScroll-1	2	DC.W hSetPage-1	3	DC.W hSetInfoRefCon-1 4	DC.W hSetInfoDraw-1	5	DC.W hSetOrigin-1	6	DC.W hSetDataSize-1	7	DC.W hSetZoomRect-1	8	DC.W hSetTitle-1	9	DC.W hSetColorTable-1 10	DC.W hSetFrameFlag-1 11	DC.W hGetOrgMask-1	12	DC.W hGetMaxGrow-1	13	DC.W hGetScroll-1	14	DC.W hGetPage-1	15	DC.W hGetInfoRefCon-1 16	DC.W hGetInfoDraw-1	17	DC.W hGetOrigin-1	18	DC.W hGetDataSize-1	19	DC.W hGetZoomRect-1	20	DC.W hGetTitle-1	21	DC.W hGetColorTable-1 22	DC.W hGetFrameFlag-1 23	DC.W hGetInfoRect-1	24	DC.W hDrawInfo-1	25	DC.W hStartInfoDraw-1 26	DC.W hEndInfoDraw-1	27	DC.W hZoomWindow-1	28	DC.W hStartDrawing-1 29	DC.W hStartMove-1	30	DC.W ckZoom-1	31	DC.W hNewSize-1	32	DC.W hTask-1	33;	ENDP;;;=======================================;          Set origin mask.;=======================================;;   IN:    a = new mask.;          <w_wind = pointer to window record.;hSetOrgMask	PROC	ldy #worgn_mask	sta [<w_wind],y	clc	No error flag.	rts	ENDP;;;=======================================;          Set maximum grow size.;=======================================;;   IN:    a = maximum window height.;          x = maximum window width.;hSetMaxGrow	PROC	ldy #wmaxHeight	jsr setLong	brl setDefFull	Check to set default max grow.	ENDP;;;=======================================;          Set amount to scroll;          when arrows selected.;=======================================;hSetScroll	PROC	ldy #vscroll;setLong	sta [<w_wind],y	iny	iny	txa	sta [<w_wind],y	clc	No error flag.	rts	ENDP;;;;=======================================;          Set amount to scroll;          when page region selected.;=======================================;hSetPage	PROC	ldy #vpage	bra setLong	ENDP;;;=======================================;          Set info	bar refCon.;=======================================;hSetInfoRefCon	PROC	ldy #wInfoRef	bra setLong	ENDP;;;=================================================;          Set info	bar draw procedure.;=================================================;hSetInfoDraw	PROC	ldy #wInfoDraw;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;          Set a long value in window record.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    y = offset into window record of field to set.;          a = low word of long value.;          x = high	word of long value.;          w_wind = pointer to window record.;;  OUT:    Carry clear, no error.;	ENTRY setLongsetLong		;       ;	sta [<w_wind],y	iny	iny	txa	sta [<w_wind],y;	clc	No error flag.	rts;	ENDP;;;=======================================;          Set content's origin.;=======================================;;   IN:    <w_param+newParam = WORD new Y	origin.;	         WORD new X	origin.;	         WORD flag.;          a = new y origin.;          x = new x origin.;hSetOrigin	PROC;		;using equates;newYorigin	equ w_worknewXorigin	equ newYorigin+2temp1	equ newXorigin+2temp2	equ temp1+4matchID	equ temp2+4;;	sta <newYorigin	Save new Y origin.	stx <newXorigin	Save new X origin.;	ldy #newParam+4	lda [<w_param],y	beq skip1	Should content be scrolled?;;; --- Scroll content to new origin ---------------------------;	jsr scrollContent	clc	No error flag.	rts;;; --- Set new origin without scrolling content ---------------;skip1	lda <newYorigin	Pass new Y origin in A, new X in X.	ldy #y_origin	jsr setLong;	jsr setScrollBars	clc	No error flag.	rts;; ; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Scroll content and set new origon.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    New origin on stack.;scrollContent		; ; 	ldx <newXorigin	lda <newYorigin	jsr new_origin;;;--------------------------------------------------------------------;          Set the frame scroll bars to	reflect the change.;--------------------------------------------------------------------;setScrollBars		; ;	jsr startFrameDraw;;; --- Set horizontal scroll bar ------------------------------;	lda #HScrollID	Get handle of horizontal scroll bar.	jsr findCtlHand	bcs skip100	Is there a horizontal scroll bar?;	pei <newXorigin	Pass new value.	phx	Pass handle of control.	pha	_SetCtlValue;	jsr derefTemp1	<temp2 = (<temp1).	lda <newXorigin	Get control's new value.	ldy #CtlrefCon	sta [<temp2],y	Remeber value for scrolling.;;; --- Set vertical scroll bar --------------------------------;skip100	lda #VScrollID	Get handle of vertical scroll bar.	jsr findCtlHand	bcs exit100	Is there a vertical	scroll bar?;	pei <newYorigin	Pass new value.	phx	Pass handle of control.	pha	_SetCtlValue;	jsr derefTemp1	<temp2 = (<temp1).	lda <newYorigin	Get control's new value.	ldy #CtlrefCon	sta [<temp2],y	Remeber value for scrolling.;exit100	brl endFrameDraw;;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;          Push handle of first control.;110= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    <w_wind = pointer to window that has frame controls.;          a = ID of control to find.;;  OUT:    Carry set if control not found.;          Carry clear if control found, x/a = handle of control.;	ENTRY findCtlHandfindCtlHand		;       ;	sta <matchID	Save ID to match.;	ldy #wFrameCtls+2	Get handle of first	control.	lda [<w_wind],y	tax	dey	dey	lda [<w_wind],y	bra enter110;lop110	jsr derefTemp1	<temp2 = (<temp1).;	ldy #ctlRefCon+2	Get control's ID.	lda [<temp2],y	cmp <matchID	beq gotit110;	ldy #ctlNext+2	Get handle of next control.	lda [<temp2],y	tax	lda [<temp2];enter110	sta <temp1	Store handle of control.	stx <temp1+2	ora <temp1+2	Any more controls?	bne lop110	sec	Control not found.	rts;gotit110	lda <temp1	Return handle of control.	ldx <temp1+2	clc	Control found flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;          Dereference <temp1.;120= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    <temp1 =	handle.;;  OUT:    <temp2 =	(temp1);derefTemp1	ldy #2	lda [<temp1],y	sta <temp2+2	lda [<temp1]	sta <temp2	rts;;; = = = = = = = = =	= = = = = = = = = =	= =;          Set window's data size.;200= = = = = = = =	= = = = = = = = = =	= =;;   IN:    <w_param+newParam = new height	of data area.;          <w_param+newParam+2 = new width of data area.;	ENTRY hSetDataSizehSetDataSize		;       ;newHeight	equ newYoriginnewWidth	equ newXorigin;;	and #$3FFF	Limit new data size.	sta <newHeight	txa	and #$3FFF	sta <newWidth;	jsr startFrameDraw;;; --- Set vertical scroll bar --------------------------------;	lda #VScrollID	Get handle of vertical scroll bar.	jsr findCtlHand	bcs skip200	Is there a vertical	scroll bar?;	                  <temp1 = control's handle.;	                  <temp2 = control's pointer.;	ldy #ctlValue	Compute maximum data size.	lda [<temp2],y	Origin,	ldy #ctlData	plus view,	clc	adc [<temp2],y	equals minimum.	cmp <newHeight	bcc ok200;	sta <newHeight	Reset data height to minimum.;ok200	ldy #data_h	Change the data width in the window.	lda <newHeight	cmp [<w_wind],y	Has there been a change?	beq skip200	If no change, don't call control.	sta [<w_wind],y	Store new data width in window record.;	pha	Pass new data size to scroll bar.	pea $FFFF	Don't change view.	pei <temp1+2	Pass handle of scroll bar.	pei <temp1	_SetCtlParams;;;; --- Set horizontal scroll bar ------------------------------;skip200	lda #HScrollID	Get handle of horizontal scroll bar.	jsr findCtlHand	bcs exit200	Is there a horizontal scroll bar?;	                  <temp1 = control's handle.;	                  <temp2 = control's pointer.;	ldy #ctlValue	Compute maximum data size.	lda [<temp2],y	Origin,	ldy #ctlData	plus view,	clc	adc [<temp2],y	equals minimum.	cmp <newWidth	bcc ok201;	sta <newWidth	Reset data width to	minimum.;ok201	ldy #data_w	Change the data width in the window.	lda <newWidth	cmp [<w_wind],y	Has there been a change?	beq exit200	If no change, don't call control.	sta [<w_wind],y	Store new data width in window record.;	pha	Pass new data size to scroll bar.	pea $FFFF	Don't change view.	pei <temp1+2	Pass handle of scroll bar.	pei <temp1	_SetCtlParams;;exit200	jsr endFrameDraw	clc	No error flag.	rts;	ENDP;;;=============================================;          Change window's origin,;          and scroll content.;=============================================;;   IN:    a = new y origin.;          x = new x origin.;          w_wind = window pointer.;;; Change History;; 21 May 89	Steven Glass;; Dispose of the temp region at exit time so it is not orphaned; when the user has his own draw proc.;new_origin	PROC;;newYorigin	equ w_worknewXorigin	equ newyorigin+2tempRgn	equ newXorigin+2deltay	equ tempRgn+4deltax	equ deltay+2;;	sta <newYorigin	Save new y origin.;	txa	Force x origin to grid.	ldy #worgn_mask	and [<w_wind],y	sta <newXorigin	Save new x origin.;;; --- Compute deltas -----------------------------------------;	ldy #x_origin	lda [<w_wind],y	sec	sbc <newXorigin	sta <deltax	Horizontal change.	lda <newXorigin	Set new origin.	sta [<w_wind],y	dey	dey	lda [<w_wind],y	sec	sbc <newYorigin	sta <deltay	Vertical change.	lda <newYorigin	Set new origin.	sta [<w_wind],y;;; --- Offset the current update region to the new position ---------------;	ldy #wupdateRgn+2	Pass handle to window's update region.	jsr pushWindLong	pei <deltax	pei <deltay	_OffsetRgn;;; --- Scroll the window's content region -------------------------------;	pha	Space for result.	pha	_NewRgn	Allocate a temp. region.	pla	sta <tempRgn	pla	sta <tempRgn+2;;; --- Scroll the content -------------------------------------;	pha	Save current port.	pha	_GetPort;	jsr hStartDrawing	Switch to window's content.;	ldx <w_wind+2	Compute address of window's port,	lda <w_wind	which is RECT to scroll.	clc	adc #wPort+GP_PortRect (Port RECT is local to content.)	bcc store1	inxstore1	phx	Pass pointer to RECT to scroll.	pha	pei <deltax	pei <deltay	pei <tempRgn+2	Update region to fill.	pei <tempRgn	_ScrollRect;	ldy #wContDraw+1	Is there a routine that will update	lda [<w_wind],y	the content?	bne redrawClobbered	If yes, redraw exposed area.;;; --- Add clobbered	region from scroll to window's update region ----------;	pei <tempRgn+2	pei <tempRgn	ldy #wPort+boundsRect+x1	lda [<w_wind],y	eor #$FFFF	inc a	pha	dey	dey	lda [<w_wind],y	eor #$FFFF	inc a	pha	_OffsetRgn	Make clobbered area	global.;	pei <tempRgn+2	Clobbered region.	pei <tempRgn	ldy #wupdateRgn+2	Add clobbered to update region.	jsr pushWindLong	ldy #wupdateRgn+2	jsr pushWindLong	_UnionRgn;	bra exit;;; --- Refresh part that was exposed by scroll -----------------;redrawClobbered		; ;	ldy #wport+visRgn+2	Save window's current visRgn.	lda [<w_wind],y	pha	lda <tempRgn+2	Replace visRgn with	clobbered region.	sta [<w_wind],y	dey	dey	lda [<w_wind],y	pha	lda <tempRgn	sta [<w_wind],y;;	ldy #wContDraw+1	Get address of content draw routine.	lda [<w_wind],y	tax	dey	lda [<w_wind],y;	phd	Save my zero page.	phb	Save current data bank.	pha	Save.;	ldy #callerDataB	Get caller's data bank pointer,	lda [<globals],y	pha	and switch to it.	plb	plb	ldy #callerDpage	Get original direct	page,	lda [<globals],y	tcd	and switch to caller's direct page.;	pla	Restore.	jsl longCall;	plb	Restore last data bank.	pld	Restore my direct page pointer.;	ldy #wport+visRgn	Restore window's original visRgn.	pla	sta [<w_wind],y	iny	iny	pla	sta [<w_wind],y;exit	pei <tempRgn+2	Free temp. region.	pei <tempRgn	_DisposeRgn	jsr zeroOrigin	Return window's origin to 0,0.	_SetPort	Restore original port.	rts	ENDP;;;=======================================;          Return origin mask.;=======================================;hGetOrgMask	PROC	ldy #worgn_mask	lda [<w_wind],y	ldx #0	clc	rts	ENDP;;;=======================================;          Return maximum grow size.;=======================================;hGetMaxGrow	PROC	ldy #wmaxheight+2	bra getLong	ENDP;;;=============================================;          Return amount to scroll;          when arrows are selected.;=============================================;hGetScroll	PROC	ldy #vscroll+2	bra getLong	ENDP;;;=============================================;          Return amount to scroll;          when page regions are selected.;=============================================;hGetPage	PROC	ldy #vpage+2	bra getLong	ENDP;;;==============================================;          Return info bar's refCon.;==============================================;hGetInfoRefCon	PROC	ldy #wInfoRef+2	bra getLong	ENDP;;;==============================================;          Return address of info;          bar's draw procedure.;==============================================;hGetInfoDraw	PROC	ldy #wInfoDraw+2	bra getLong	ENDP;;;==============================================;          Return content's origin.;==============================================;hGetOrigin	PROC	ldy #y_origin+2	bra getLong	ENDP;;;========================================================;          Return pointer to window's title.;========================================================;hGetTitle	PROC	ldy #wTitle+2	bra getLong	ENDP;;;========================================================;          Return pointer to window's color table.;========================================================;;  OUT:    x/a = pointer or handle of window's color table (never null).  High bit set if handle.;hGetColorTable	PROC;	ldy #wcolor+2	Fetch color table field from window record.	lda [<w_wind],y	tax	dey	dey	lda [<w_wind],y	bne @exit	Is the color table a pointer?	txy	bne @exit;;; --- NIL color table, use default.;	ldy #defWindClr+2	Use default color table.	lda [<globals],y	tax	dey	dey	lda [<globals],y;@exit	clc	No error flag.	rts	ENDP;;;==============================================;          Return window's data size.;==============================================;hGetDataSize	PROC	ldy #data_h+2;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;          Fetch a long value from a window record.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    y = offset to high word of long in window record.;          w_wind = pointer to window record.;;  OUT:    x/a = long fetched from window record.;          Carry clear, no error.;	ENTRY getLonggetLong		;       ;	lda [<w_wind],y	tax	dey	dey	lda [<w_wind],y;	clc	No error flag.	rts	ENDP;;;;==============================================;          Set new zoom RECT in window.;==============================================;;   IN:    <w_wind = window to set zoom RECT in.;          x/a = pointer to new zoom RECT.;hSetZoomRect	PROC;		;using equates;newZoom	equ w_worktemp1	equ newZoom+4;;	sta <newZoom	Save pointer to new	zoom RECT.	stx <newZoom+2;	ldy #wframe	Reset zoomed flag.	lda [<w_wind],y	and #_F_ZOOMED	Clear zoomed bit.	sta [<w_wind],y;;; --- Move new zoom	RECT into window record ------------------;	jsr hGetZoomRect	Compute address of wfull field.	sta <temp1	stx <temp1+2;	ldy #x2	Move new RECT into window record.lop1	lda [<newZoom],y	sta [<temp1],y	dey	bpl lop1;	brl setDefFull	Check to set default zoom RECT.	ENDP;;;==============================================;          Change window's title.;==============================================;;   IN:    <w_wind = pointer to window to	set new title.;          x/a = pointer to new title.;hSetTitle	PROC;	phx	Save title.	pha;	ldy #wtitle+2	Is there a handle there now?	lda [<w_wind],y	bpl @ok1	and #$7FFF	Free the exsisting handle first.	pha	dey	dey	lda [<w_wind],y	pha	_DisposeHandle;@ok1	pla	Restore new title.	plx;	ldy #wtitle	Store new title.	sta [<w_wind],y	iny	iny	txa	sta [<w_wind],y;	jsr startFrameDraw	jsr setTitleWidth	Set the width of the new title.;	lda #titleBarID	Find title bar control.	jsr findCtlHand	bcs exit	Control found?;	phx	Pass handle of control to DrawOneCtl/	pha;	pha	Pass new value (not	used).	phx	Pass handle of control to SetCtlValue.	pha	_SetCtlValue	Have control compute title's x1 position.;	ldy #wFrame	Is the window visible?	lda [<w_wind],y	and #F_VIS	bne ok1	If not, don't draw.	pla	Get rid of handle.	pla	bra exit	And don't draw.;ok1	_DrawOneCtl	Redraw the title bar.;;; --- Draw the info also, because system disk 3.1 and before did, some apps need this ---------------;	lda #infoBarID	Find info bar control.	jsr findCtlHand	bcs exit	Control found?	phx	Pass handle of info	bar control.	pha	_DrawOneCtl	Draw the info bar.;exit	brl endFrameDraw	ENDP;;;==============================================;          Change window's color table.;==============================================;;   IN:    <w_wind = pointer to window, zero to replace system table.;          x/a = pointer to new color table, zero to use default color table.;hSetColorTable	PROC;	tay	Use default color table?	bne ok1	txy	bne ok1	lda #def_color	Use default color table.	ldx #def_color>>16;ok1	phx	Save new color table.	pha;	ldy #wColor+2	Is there a handle there now?	lda [<w_wind],y	bpl @ok2	and #$7FFF	Free the exsisting handle first.	pha	dey	dey	lda [<w_wind],y	pha	_DisposeHandle;@ok2	pla	Restore new color table.	plx;	ldy #wColor	Replace window's color table.	sta [<w_wind],y	iny	iny	txa	sta [<w_wind],y;exit	rts;;; --- Default pattern/color table for windows ------------------;def_color	DC.W $0000	Frame outline.	DC.W $0F0F	Unused/Inactive Bar/Inactive Title/Title.	DC.W $0000	Title bar.	DC.W $F0F0	Inside grow box.	DC.W $00F0	Inside info bar.;	ENDP;;;==============================================;          Change window's frame flags.;==============================================;;   IN:    <w_wind = window pointer.;          a = new frame flag.;hSetFrameFlag	PROC	ldy #wframe	sta [<w_wind],y	rts	ENDP;;;===============================================================;          Return pointer to window's zoom RECT field.;===============================================================;;   IN:    <w_wind = window pointer.;;  OUT:    x/a = pointer to window's zoom RECT field.;hGetZoomRect	PROC	ldx <w_wind+2	lda <w_wind	clc	adc #wfull	bcc exit	inxexit	rts	ENDP;;;==============================================;          Return window's frame flags.;==============================================;;   IN:    <w_wind = window pointer.;;  OUT:    a = window's frame flags.;hGetFrameFlag	PROC	ldy #wframe	lda [<w_wind],y	rts	ENDP;;;==============================================;          Return info bar RECT.;==============================================;;   IN:    <w_wind = window pointer.;          x/a = place to store RECT.;;  OUT:    Carry clear if there is an info bar.;hGetInfoRect	PROC;		;using equates;desRect	equ w_workctlHand	equ desRect+4srcRect	equ ctlHand+4;;	sta <desRect	Place to store info	bar RECT.	stx <desRect+2;	lda #infoBarID	Pass ID of info bar	control.	jsr findCtlHand	Get info bar control handle.	bcs zeroDesRect	Is there an info bar control?;	sta <ctlHand	stx <ctlHand+2;	ldy #2	Dereference control	handle.	lda [<ctlHand],y	tay	lda [<ctlHand]	clc	Compute pointer to ctlRect foeld.	adc #ctlRect	bcc store1	inystore1	sta <srcRect	sty <srcRect+2;	ldy #x2lop1	lda [<srcRect],y	sta [<desRect],y	dey	dey	bpl lop1;	pei <desRect+2	Pass pointer of destination RECT.	pei <desRect	jsr pushLineSize	Pass size of lines.	_InsetRect	Return inside RECT of info bar.;	clc	There is an info bar.	rts;;; --- Zero destination RECT ----------------------------------;	ENTRY zeroDesRectzeroDesRect		;       ;	ldy #x2	lda #0lop2	sta [<desRect],y	dey	dey	bpl lop2	sec	No info bar.	rts;	ENDP;;;===========================================================;          Setup to	draw in window's info bar.;===========================================================;;   IN:    <w_wind = window pointer.;          x/a = pointer of where to store info bar RECT.;hStartInfoDraw	PROC	jsr hGetInfoRect	bcs ok1	Is there an info bar?;	ldy #wframe	Is the window visible?	lda [<w_wind],y	and #F_VIS	bne ok1	brl zeroDesRect	Return zero RECT.;ok1		; ;;; --- Clip visRgn to window's above --------------------------;	ENTRY clipVisclipVis		;       ;clipVisRgn	equ w_workwindPtr	equ clipVisRgn+4;	pha	pha	_GetWMgrPort	pla	sta <windPtr	pla	sta <windPtr+2;	ldy #clipRgn	lda [<windPtr],y	sta <clipVisRgn	iny	iny	lda [<windPtr],y	sta <clipVisRgn+2;	pha	pha	_FrontWindow	pla	plx	sec	sbc #wPort	bcs enter1	dex	bra enter1;lop1	pei <clipVisRgn+2	Pass region.	pei <clipVisRgn	ldy #wStrucRgn+2	Pass window's strucRgn to subtract.	lda [<windPtr],y	pha	dey	dey	lda [<windPtr],y	pha	pei <clipVisRgn+2	Pass result region.	pei <clipVisRgn	_DiffRgn;	ldy #2	Get pointer to next	window.	lda [<windPtr],y	tax	lda [<windPtr];enter1	sta <windPtr	stx <windPtr+2;	cmp <w_wind	bne lop1	cpx <w_wind+2	bne lop1;	brl startFrameDraw	ENDP;;;============================================================;          Redraw interior of window's info bar.;============================================================;hDrawInfo	PROC	ldy #wFrame	Is the window visible?	lda [<w_wind],y	and #F_VIS	bne ok1	rts	If invisible, don't draw.;ok1	jsr clipVis	Set visRgn to clip windows above.;	lda #infoBarID	Pass ID of info bar	control.	jsr findCtlHand	Find handle of info	bar control.	bcs skip1	No info bar control?;	phx	Pass handle of info	bar control.	pha	_DrawOneCtl	Draw the info bar.;skip1		; ;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;          Restore states after info bar draw.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;	ENTRY hEndInfoDrawhEndInfoDraw		;       ;	pea screenRect>>16	Restore Window Manager's clipRgn to full.	pea screenRect	_ClipRect;	brl endFrameDraw;screenRect	DC.W 0,0,200,640;	ENDP;;;=================================================;          Flip a window's zoom position.;=================================================;;   IN:    w_wind = window to zoom (or unzoom).;;  OUT:    None.;hZoomWindow	PROC; --- Flip Full flag -------------------------------------------------;	ldy #wframe	Flip full window flag.	lda [<w_wind],y	eor #F_ZOOMED	sta [<w_wind],y;	and #F_ZOOMED	Going to zoomed?	bne skip1;; --- Unzooming -------------;	jsr swap_origin	Replace old origin.	bra skip2;; --- Zooming ---------------;skip1	jsr saveWOrigin	Save current, unzoomed, origin.;;; --- Swap Full RECT wth current content size ------------------------;skip2	jsr saveWRect;;; --- Reset orgin if needed -------------------------------------------;	lda <w_rect+x2	sec	sbc <w_rect+x1	tax	Pass content width in X.;	lda <w_rect+y2	sec	sbc <w_rect+y1	Pass content height	in A.	jsr ck_origin	Check origin and reset if needed.;;; --- Now resize and position window ----------------------------------;	pea 0	Redraw entire content region.	jsr pushrect	Pass pointer to new	size of content.	ldx <w_wind+2	Pass pointer to graphPort.	lda <w_wind	clc	adc #wPort	bcc store1	inxstore1	phx	pha	_ResizeWindow;	clc	No error flag.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;          Save window origin to its wold fields.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    w_wind = pointer to window.;;  OUT:    woldYOrg	field = y_origin field.;          woldXOrg	field = x_origin field.;	ENTRY saveWOriginsaveWOrigin		;       ;	ldy #y_origin	Save current, unzoomed, origin.	lda [<w_wind],y	ldy #woldYOrg	sta [<w_wind],y;	ldy #x_origin	lda [<w_wind],y	ldy #woldXOrg	sta [<w_wind],y	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = =;          Save window size/position to	its wfull field.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    <w_wind = pointer to window.;;  OUT:    <w_rect = window's wfull field.;          <wfull =	window's current size.;	ENTRY saveWRectsaveWRect		;       ;	ldy #wcontRgn	jsr getRgnBounds	<w_wrect = content bounds.;	ldy #wfull+x2	last position = w_wrect (saved position).	ldx #x2lop2	lda [<w_wind],y	Put current wFull into 'w_rect'.	sta <w_rect,x	lda <w_wrect,x	Replace wFull with current content size.	sta [<w_wind],y	dey	dey	dex	dex	bpl lop2;	rts;	ENDP;;;================================================;          Set up window for drawing.;================================================;;   IN:    w_wind = window pointer.;;  OUT:    Nothing.;hStartDrawing	PROC	ldx <w_wind+2	Pass pointer to window's port.	lda <w_wind	clc	adc #wPort	bcc store1	inxstore1	phx	pha	_SetPort;	ldy #x_origin	lda [<w_wind],y	tax	dey	dey	lda [<w_wind],y	jsr setTheOrigin	clc	No error flag.	rts	ENDP;;;==============================================;          Called with new position.;==============================================;;   IN:    <w_wind = pointer to window.;          a = new y position.;          x = new x position.;;  OUT:    a = new y position.;          x = new x position.;hStartMove	PROC	pha	Save new y.	phx	Save new x.;	jsr ckZoom	Save position if zoomed.;	plx	Return new x.	pla	Return new y.	rts	ENDP;;;==================================================;          If window is Zoomed, unzoom it.;==================================================;;   IN:    w_wind = pointer to window.;;  OUT:    If window is currently zoomed:;                Window's zoomed flag is cleared.;                Save current position as next zoomed position.;                Save current origin as	next zoomed origin.;ckZoom	PROC	ldy #wframe	Is the window currently zoomed?	lda [<w_wind],y	and #F_ZOOMED	beq exit	If not, exit.;;; --- Mark the window as not zoomed ----------------------------------------;	lda [<w_wind],y	Clear zoomed flag.	eor #F_ZOOMED	sta [<w_wind],y;;; --- Save the window's current size, position, and origin (zoomed size) ----;	jsr saveWRect	wfull = current content size / position.	jsr saveWOrigin	woldYOrg, woldXOrg = y_origin, x_origin.;exit	rts	ENDP;;;=======================================================;          Swap 'y_origin' and 'x_origin';          with 'woldYOrg' and 'woldXOrg'.;=======================================================;;   IN:    w_wind = pointer to window.;swap_origin	PROC	ldy #y_origin	ldx #woldYOrg	jsr swap_word	Swap 'y_origin' and	'woldYOrg'.;	iny	iny	inx	inx;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;          Swap 2 words in the window .; = = = = = = = = =	= = = = = = = = = =	= = = = =;	ENTRY swap_wordswap_word		;       ;;   IN:    y = offset to one word to swap.;          x = offset to the other word	to swap.;          w_wind = pointer to window.;;  OUT:    y = same	as in.;          x = same	as in.;	phx	Save offset to param2.	phy	Save offset to param1.;	lda [<w_wind],y	Get param1,	pha	and save it.	txy	Get offset to param2.	lda [<w_wind],y	Get param2,	tax	and save in X.	pla	Retrieve param1,	sta [<w_wind],y	and store it where param2 was.	ply	Retrieve offset to param1.	txa	Retrieve param2,	sta [<w_wind],y	and store it where param1 was.	plx	Retrieve offset to param2.	rts	ENDP;;;=====================================================;          Adjust origin if new size to;          larger than data area.;=====================================================;;   IN:    w_param = pointer to new height, width.;;  OUT:    y_origin	reset if needed.;          x_origin	reset if needed.;hNewSize	PROC	sta <w_work	Save pointer to new	height / width.	stx <w_work+2;	ldy #2	Pass new height / width.	lda [<w_work],y	tax	Pass new width in X.	lda [<w_work]	Pass new height in A.;	ldy #wMaxHeight	New height cannot be greater than max.	cmp [<w_wind],y	bcc ok1	lda [<w_wind],y	Use max height.ok1	pha	Save new height.;	ldy #wMaxWidth	txa	cmp [<w_wind],y	bcc ok2	lda [<w_wind],y;ok2	ldy #2	Store new width.	sta [<w_work],y	tax	Pass width in x.;	pla	Get new height.	sta [<w_work]	Store new height.;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;          Adjust origin if new size to;          larger than data area.;100= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    a = new content height.;          x = new content width.;;  OUT:    a = FALSE if origin reset, TRUE if not moved.;          y_origin	reset if needed.;          x_origin	reset if needed.;	ENTRY ck_originck_origin		;       ;newHeight	equ w_worknewWidth	equ newHeight+2w_uncovered	equ newWidth+2;;	sta <newHeight	Save new content height.	stx <newWidth	Save new content width.;	stz <w_uncovered	Default to draw only what's uncovered.	inc <w_uncovered;;; --- Does window want its origin moved? --------------------------------;	ldy #wframe	lda [<w_wind],y	and #F_FLEX	beq fixOrigin;;; ------ If not, the window's data size must be set -----------------;	ldy #y_origin	lda [<w_wind],y	y_origin plus,	clc	adc <newHeight	content height,	ldy #data_h	equals total data height exposed.	cmp [<w_wind],y	Is the new height greater than the old?	bcc skip100	sta [<w_wind],y	If yes, set the height to the greater.;skip100	ldy #x_origin	lda [<w_wind],y	x_origin plus,	clc	adc <newWidth	content width,	ldy #worgn_mask	and [<w_wind],y	ldy #data_w	equals width of data exposed.	cmp [<w_wind],y	Is the new width greater than the old?	bcc exit100	sta [<w_wind],y	If yes, set the width to the greater.	bra exit100;;; --- Check Y origin -----------------------------------;fixOrigin	ldy #y_origin	lda [<w_wind],y	y_origin plus,	clc	adc <newHeight	content height,	ldy #data_h	equals total data height exposed.	cmp [<w_wind],y	Is it greater than the data height?	bcc ok100	beq ok100;;; ------ Reset Y origin -------------------------------;	lda [<w_wind],y	sec	sbc <newHeight	bcs ok101	lda #0	Minimum.ok101	ldy #y_origin	sta [<w_wind],y;	stz <w_uncovered	Set flag to redraw entire content region.;;; --- Check X origin -----------------------------------;ok100	ldy #x_origin	lda [<w_wind],y	x_origin plus,	clc	adc <newWidth	content width,	ldy #worgn_mask	and [<w_wind],y	ldy #data_w	equals width of data exposed.	cmp [<w_wind],y	Is it greater than the data width?	bcc exit100	beq exit100;;; ------ Reset x_orgin ----------------------------------;	lda [<w_wind],y	sec	sbc <newWidth	bcs ok102	lda #0	Minimum.;ok102	ldy #worgn_mask	Force X origin to desired boundary.	and [<w_wind],y;	ldy #x_origin	sta [<w_wind],y;	stz <w_uncovered	Set flag to redraw entire content region.;exit100	lda <w_uncovered	Return content draw	flag.	clc	No error flag.	rts	ENDP;;;============================================;          Handle TaskMaster task.;============================================;;   IN:    x/a = pointer to task record.;          <w_param =	pointer to:;	          WORD - request code.;	          WORD - defProc ID.;	          LONG - task record pointer.;	          WORD - result from FindWindow.;          <w_wind = pointer to window's record.;          <taskRec+taskData = pointer to window's port.;;  OUT:    a = zero	if task handled, else result from FindWindow.;          x = task	action.;hTask	PROC;		;using equates;taskRec	equ w_workfoundCtl	equ taskRec+4;;	sta <taskRec	stx <taskRec+2;;; --- Dispatch to the specific task handler --------------------------;	ldy #newParam+4	Get result from FindWindow.	lda [<w_param],y	sec	sbc #$13	bcc cant	cmp #9	bcc okcant	lda #6	Force call to cantHandle.ok	asl a	tax	jmp (taskDoers,x);taskDoers	DC.W content	$13  0	DC.W drag	$14  1	DC.W grow	$15  2	DC.W goAway	$16  3	DC.W zoom	$17  4	DC.W infoBar	$18  5	DC.W cantHandle	$19  6	DC.W cantHandle	$1A  7	DC.W frame	$1B  8;;; = = = = = = = = =	= = = = = = = = = =	=;          wInInfo;100= = = = = = = =	= = = = = = = = = =	=;infoBar	ldy #taskMask	Check if window should be made top.	lda [<taskRec],y	and #TM_INFO	beq ok100	ldx #0	No action taken.	lda #wInInfo	Return in info flag.	rts;ok100	jsr check_top	Check if window is active,	bcc cantHandle	if the window has to be made active;	                  it means the event is	handled.;	ldx #wInInfo	Return action taken.	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          TaskMaster can't handle;          this task (must not be a Master).;110= = = = = = = =	= = = = = = = = = =	=;cantHandle	ldy #newParam+4	Return the code passed to me, back.	lda [<w_param],y	ldx #0	No action.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          Drag Window.;120= = = = = = = =	= = = = = = = = = =	=;;; ------ Check if window should be brought to the top --------------;drag	ldy #taskMask	Check if window should be made top.	lda [<taskRec],y	and #TM_DRAGW	bne ok120	ldx #0	No action taken.	lda #wInDrag	Return in drag flag.	rts;ok120	ldy #wFrame	Check if window can	be moved.	lda [<w_wind],y	and #F_MOVE	beq exit120;	jsr startToGlobal	Convert starting point to global.;	ldx #0	Default grid, don't bring window to top.;	ldy #modif	Read modifier keys state from event.	lda [<taskRec],y	and #K_COMMAND	Is the command key down?	bne skip120;	ldx #$8000	Default grid, bring	window to front.;;; ------ Now drag the window in its current plane ---------------------;skip120	phx	Pass drag flag.	jsr pushStartPos	Pass starting point.	pea 8	Grace buffer.	pea 0	Use default bounds RECT.	pea 0	jsr pushWgraphPort	Pass pointer to window's graphPort.	_DragWindow;exit120	ldx #wInDrag	Window was dragged action message.	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          wInContent;130= = = = = = = =	= = = = = = = = = =	=;content	ldy #taskMask	Check if window should be made top.	lda [<taskRec],y	and #TM_CONTENT	beq exit130;	jsr check_top	bcc cantHandle	Did the window have	to be selected?;	                  	If not, return wInContent message.;	ldy #wframe	Does the window wish to reuse the button?	lda [<w_wind],y	and #F_QCONTENT	bne cantHandle	Reuse the button down.;exit130	ldx #wInContent	Button in content brought window to top.	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          wInGoAway;140= = = = = = = =	= = = = = = = = = =	=;goAway	jsr startToGlobal	Convert starting point to global.;	pha	Return space.	jsr pushStartPos	Pass starting point.	jsr pushWgraphPort	Pass pointer to window's graphPort.	_TrackGoAway	pla	Was the user inside	the close box?	bne exit140	-yes.;	ldx #wInGoAway	User clicked in close box, but it was	lda #0	Task handled.	rts;exit140	ldx #0	No action.	lda #wInGoAway	Close window.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          wInZoom;150= = = = = = = =	= = = = = = = = = =	=;zoom	jsr startToGlobal	Convert starting point to global.;	pha	Return space.	jsr pushStartPos	Pass starting point.	jsr pushWgraphPort	Pass pointer to window's graphPort.	_TrackZoom	ldx #wTrackZoom	Tell caller that the zoom box was tracked,	pla	but not selected, just in case.	beq exitZoom	Did the user select	the zoom box?;;; ---------- Zoom window ------------------------------------------;	jsr pushWgraphPort	Save pointer to window's graphPort.	_ZoomWindow	(Window pointer already on stack.);	ldx #wInZoom	Window was zoomed.exitZoom	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          wInGrow;160= = = = = = = =	= = = = = = = = = =	=;grow	jsr check_top	Check if window is top most.	bcc ok160	If not, made top, and done.;	lda #0	Task handled.	tax	No action.	rts;ok160	jsr startToGlobal	Convert starting point to global.;	pha	Space for result.	pha	pea 100	Minimum width allowed.	pea 40	Minimum height allowed.	jsr pushStartPos	Pass starting point.	jsr pushWgraphPort	Pass pointer to window's graphPort.	_GrowWindow;	                  Pass new height/width	from GrowWindow.	jsr pushWgraphPort	Save pointer to window's graphPort.	_SizeWindow	(Window pointer already on stack.);	ldx #wInGrow	Window resized.	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	=;          wInFrame;170= = = = = = = =	= = = = = = = = = =	=;frame	jsr check_top	Check if window is top most.	bcs exit171	If not, made top and task handled.;;; --- Check for hit	on frame control -------------------------;	jsr startFrameDraw;	jsr startToGlobal	Convert starting point to global.;	pha	Space for result.	lda #foundCtl	Pass place to store	handle of control.	jsr pushDpage	jsr pushStartPos	Pass starting point.	pha	Pass pointer to window.	pha	_GetPort	Current port is port to check.	_FindControl	pla	Control found?	beq exit170;	pha	Space for result.	pha	pei <foundCtl+2	Pass handle of found control.	pei <foundCtl	_GetCtlRefCon	pla	pla	Get control's ID.	cmp #HScrollID	Is the control a scroll bar?	beq ok170	cmp #VScrollID	beq ok170;exit170	jsr endFrameDraw;exit171	ldx #wHitFrame	Tell caller user clicked in window frame.	lda #0	Task handled.	rts;;; --- Track the control --------------------------------------;ok170	pha	Space for result.	jsr pushStartPos	Pass starting point.	pea TaskScroll>>16	Pass action procedure address.	pea TaskScroll	w_wind = window pointer for TrackScroll.	pei <foundCtl+2	Pass handle of control to track.	pei <foundCtl	_TrackControl	pla	Result not used.;	jsr endFrameDraw;	ldx #wInFrame	Scroll bar may have	changed.	lda #0	Task handled.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = =;          Check if	window is top.;190= = = = = = = =	= = = = = = = = = =	= = =;;   IN:    w_wind = pointer to window's record.;;  OUT:    Carry clear of window already on top.;          Carry set if window made top.;check_top		; ;	pha	Space for result.	pha	_FrontWindow	pla	Get pointer to top graphPort.	plx;	ldy #taskData	Compare top to this	window.	cmp [<taskRec],y	bne totop	txa	iny	iny	cmp [<taskRec],y	bne totop	clc	Window is on top flag.	rts;totop	jsr pushWgraphPort	Pass pointer to window's graphPort.	_SelectWindow	Bring the window to	the top.;	sec	Window made top window.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Push long value from task record.;200= = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;   IN:    <taskRec	= pointer to task record.;;  OUT:    Pointer to window graphPort on stack.;pushWgraphPort		; ;	ldy #taskData+2	bra pushTaskField;pushStartPos		; ;	ldy #where+x1;pushTaskField		; ;	plx;	lda [<taskRec],y	pha	dey	dey	lda [<taskRec],y	pha;	phx	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;          Convert starting point to global.;210= = = = = = = =	= = = = = = = = = =	= = = = = = = = =;startToGlobal		; ;	lda #taskRec+where	Pass pointer to starting point.	jsr pushDpage	_LocalToGlobal	rts;	ENDP;;;========================================;          Setup to	draw frame.;========================================;;   IN:    <w_wind = pointer to window record of window to draw.;startFrameDraw	PROC	pei <w_wind+2	Pass window record pointer.	pei <w_wind	_StartFrameDrawing;	rts	ENDP;;;===========================================;          Undo setup to draw frame.;===========================================;;   IN:    startFrameDraw must have been called.;endFrameDraw	PROC;	_EndFrameDrawing	rts	ENDP;;;///////////////////////////////////////////////////;          Action routine for scrolling;          from scroll bars in window frame.;///////////////////////////////////////////////////;;   IN:    PUSH:WORD - part code.;          PUSH:LONG - handle of control.;;          Direct page is same as defProc's.;                <w_wind = pointer to window this scroll bar controls.;TaskScroll	PROC;		;using equates;return	equ 1control	equ return+3part	equ control+4;ctlPtr	equ w_worksAmount	equ ctlPtr+4pAmount	equ sAmount+2horDelta	equ pAmount+2verDelta	equ horDelta+2;;	lda control+2,s	tax	lda control,s	jsr getcontrol2	Get control pointer.;	ldx #vscroll	ldy #CtlFlag	lda [<ctlPtr],y	and #DIR_SCROLL	Vertical or horizontal?	beq ok1	ldx #hscrollok1	txy	lda [<w_wind],y	sta <sAmount	Scroll amount.	iny	iny	iny	iny	lda [<w_wind],y	bne store1	Use default page value?;	ldx #CtlRect+y2	ldy #CtlFlag	lda [<ctlPtr],y	and #DIR_SCROLL	Vertical or horizontal?	beq ok4	inx	inxok4	txy	lda [<ctlPtr],y	y2 or x2.	dey	dey	dey	dey	sec	sbc [<ctlPtr],y	y1 or x1.	sbc #10;          store1	sta <pAmount	Page amount.;;	lda part,s	and #$7F	bne ok5	brl exitok5	asl a	tax	ldy #CtlValue	Common need.	jmp (part_act-2,x);part_act	DC.W act_thumb	1	DC.W act_butt	2 Just exit.	DC.W act_check	3 Just exit.	DC.W act_radio	4 Just exit.	DC.W act_up	5	DC.W act_down	6	DC.W act_pup	7	DC.W act_pdown	8;;;----------------------------------;          Track thumb.;----------------------------------;act_thumb	lda [<ctlPtr],y	Get new value (was set by Control Manager),	tax		(Save the actual new value.)	pha	and put on stack like everyone else.;	ldy #CtlrefCon	Now get last value,	lda [<ctlPtr],y	and make current value,	ldy #ctlValue	so code can compute change (delta) in position for scroll.	sta [<ctlPtr],y	ldy #ctlRefCon	Save actual new value.	txa	sta [<ctlPtr],y	bra new_value	Now go do scroll.;;;------------------------------------------;          Track up/left arrow.;------------------------------------------;act_up	lda [<ctlPtr],y	sec	sbc <sAmount	bra enter1;;;------------------------------------------;          Track down/right arrow.;------------------------------------------;act_down	lda <sAmount	bra add_value;;;------------------------------------------;          Track up/left page.;------------------------------------------;act_pup	lda [<ctlPtr],y	sec	sbc <pAmountenter1	pha	Pass new value to SetCtlValue.	bcs new_value	lda #0	bra reset;;;------------------------------------------;          Track down/right page.;------------------------------------------;act_pdown	lda <pAmount;;add_value	clc	adc [<ctlPtr],y	Add to current value.	pha	Pass new value to SetCtlValue.;	ldy #CtlData+2	Maximum value allowed is,	lda [<ctlPtr],y	data size,	dey	dey	sec	sbc [<ctlPtr],y	less view size.	cmp 1,s	bcs new_value	Is max greater than	new value?;reset	sta 1,s	If not, set to max.;;; ------ Compute the RECT to scroll and	switch to window's port --------;new_value	ldy #ctlFlag	Is this the horizontal scroll bar.	lda [<ctlPtr],y	and #DIR_SCROLL	beq @skip1	ldy #worgn_mask	Mask position of horizontal scroll bar.	pla	and [<w_wind],y	pha@skip1;	ldy #CtlValue	lda [<ctlPtr],y	Old value,	sec	sbc 1,s	less new value	tax	is change.	ldy #CtlFlag	lda [<ctlPtr],y	ldy #0	Y = zero cause it's the other delta and only one can change.	and #DIR_SCROLL	Vertical or horizontal?	beq ok3	tya	txy	taxok3	sty <horDelta	Horizontal change.	stx <verDelta	Vertical change.;	ldy #y_origin	Current y origin,	lda [<w_wind],y	sec	sbc <verDelta	less y delta,	pha	equals new y origin.;	ldy #x_origin	Current x origin,	lda [<w_wind],y	sec	sbc <horDelta	less x delta.	bpl @ok	lda #0	New X can't be negative. Sometimes the x origin of the;		window doesn't match the scroll bar value.@ok	tax	Pass new X origin.	pla	Pass new Y origin.	jsr new_origin;;; --- Set scroll bar to new value ----------------------------;	jsr getcontrol	Dereference control's handle.;	ldy #CtlRefCon	Save new position as old position.	lda [<ctlPtr],y		Save old in case of thumb.	tax	lda 1,s	sta [<ctlPtr],y;;; ------ Special case when thumb dragged.;	lda part+1,s	If page or arrows then ready to set new position.	bpl @ok1;	txa	Actual value into A.	ldy #ctlValue	sta [<ctlPtr],y	Set new value, position of thumb already correct.;@ok1;		New value already on stack.	lda control+4,s	Pass handle of control.	pha	lda control+4,s	pha	_SetCtlValue;;;act_butt		; act_check		; act_radio		; ;EXIT	lda 0,s	sta 6,s	lda 2,s	sta 8,s	pla	pla	pla	rtl;;;getcontrol	lda control+6,s	tax	lda control+4,s;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;          Convert handle into pointer.; = = = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    x/a = handle.;;  OUT:    <ctlPtr = pointer (handle dereferenced).;getcontrol2		; ;	sta <ctlPtr	stx <ctlPtr+2;	ldy #2	lda [<ctlPtr],y	tay	lda [<ctlPtr]	sta <ctlPtr	sty <ctlPtr+2	rts;	ENDP;;;            APPEND	ALERTDEF.ASM	TITLE 'Apple IIGS Window Manager                   ALERTDEF.ASM';;          Copyright Apple Computer, Inc. 1986-1987;          All rights reserved;          Written by Dan Oliver;;        This module contains the window definition procedure;        of a standard alert window.;;;====================================================;        Alert window definition procedure.;====================================================;;   IN:    PUSH:LONG - space for result.;          PUSH:LONG - pointer to Window Manager globals.;          PUSH:WORD - operation to perform.;          PUSH:LONG - pointer to window's port.;          PUSH:LONG - addtional parameter defined by operation.;          JSL to defProc.;;          For this	defProc the direct page is the Window Manager's.;	EXPORT alertDefProcalertDefProc	PROC;;; --- Set up for defProc call --------------------------------;	jsr startup;;; --- Dispatch to operation handler --------------------------;	lda <operation	cmp #11	bcs skip2	asl a	tax	jsr (taskTable,x)	sta <result	stx <result+2	bcs skip1skip2	ldy #0	No error code.;;; --- Return to caller ---------------------------------------;skip1	brl shutdown;;taskTable	DC.W alertDraw	0 Draw window frame.	DC.W alertHit	1 Hit test window.	DC.W alertRgns	2 Compute struc and	content regions.	DC.W alertInit	3 Additional initailization.	DC.W docDispose	4 Additional diaposal.	DC.W alertDrag	5 Return address of	draw frame routine.	DC.W alertGrow	6 Draw grow window outline.	DC.W docRecSize	7 Return window record size.	DC.W docPosition	8 Return position and size of window.	DC.W docBehind	9 Return where window goes in list.	DC.W docCallDefProc	10Generic call to defProc.;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 0        Draw alert window's frame.;100= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    w_wind = window to draw.;          w_wrect = coordinates of entire window in local coordinates.;          justInfo	= TRUE to only draw	the info bar.;;  OUT:    x/a = result.;alertDraw		; ;frame	equ w_work	Window's frame type.highlight	equ frame+2	TRUE if this window	is on top.;;	ldy #wFrame	lda [<w_wind],y	sta <frame	For easy access.	and #F_HILITED	Get highlight bit.	sta <highlight	Set flag.;	jsr setcolorptr	Set pointer to window's color table.;;; --- Set frame outline pattern/color --------------------;	ldy #FRAME_CLR	jsr setoutline	Set pen color and pattern.;	jsr getLocalRect	<w_rect & <w_wrect = frame RECT in local.;;; --- Draw an alert	frame -----------------------------------;; ------ Draw outside frame ----------------------------------;	jsr pushrect	For InsetRect call.;	jsr getLineSize	inc a	Width = 2 in 320, 3	in 640.	pha	ldy #screenMode	640 mode?	lda [<globals],y	beq ok100	pla	Width = 2 in 640.	dec a	pha;ok100	pla;	pha	For InsetRect call.	phx;	pha	phx	_SetPenSize;	jsr framerect	Draw outline around	the window.;	_InsetRect;;; ------ Draw middle frame ---------------------------------------------;	ldy #GROW_CLR+1	jsr setoutline	Set pen color and pattern.;	jsr pushrect	For InsetRect call.;	jsr getLineSize	asl a	inc a	Width = 3 in 320, 5	in 640.	inx	Line height.;	pha	For InsetRect call.	phx;	pha	phx	_SetPenSize;	jsr framerect	Draw outline around	the window.;	_InsetRect;;; ------ Draw inside frame ---------------------------------------------;	ldy #INFOR_CLR+1	jsr setoutline	Set pen color and pattern.;	jsr framerect	Draw outline around	the window.;	jsr unlockColor	Leave color table unlocked.	clc	No error.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =; 1        Test hit	on a standard documnet window.;200= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =;;   IN:    <w_param =	y point to check.;          <w_param+2	= x point to check.;;  OUT:    a = part	point is zero if no	point found,;              else	a = wInContent;	    wInDrag;	    wInGrow;	    wInGoAway;	    wInZoom;	    wInInfo;	    wInVScroll;	    wInHScroll;	    wInFrame;  OUT:    x/a = result.;;alertHit		; ;savframe	equ w_work+4;;	pha	Space for returned value.	lda #w_param	Pass pointer to point to check.	jsr pushDpage	ldy #wcontRgn+2	jsr pushWindLong	Pass handle of region to check.	_PtInRgn	pla	Get result.	beq not_content;	lda #wInContent	On content.	clc	No error.	rts;;not_content		; ;	ldy #wframe	Is there a title bar?	lda [<w_wind],y	and #F_MOVE	bne ok_move;	lda #wInFrame	On window frame, but no region.	clc	No error.	rts;ok_move	lda #wInDrag	On title bar.	clc	No error.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =; 3        Perform additional initialization.;400= = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    w_wrect = content area in global coordinates.;          w_param = pointer to parameter	list.;          w_wind = window pointer.;;  OUT:    x/a = result.;alertInit		; ;;;; --- Make sure parameter list is the proper size ------------;	lda [<w_param]	Check length paramter.	cmp #p_size	Proper size?	beq ok400;	ldy #$0E01	Bad parameter list length error.	sec	Error flag.	rts;ok400		; ;;; --- Transferr data from parameter list to window record ----;	ldy #wframe	Place in record to put parameter list.	ldx #p_wframelop2	phy	txy	lda [<w_param],y	ply	ora [<w_wind],y	OR to not disturb wFrame bits already set.	sta [<w_wind],y	iny	iny	inx	inx	cpx #p_updateDraw	bne lop2;	ldy #p_wRefCon	Set the wRefCon field.	ldx #wRefCon+2	jsr setWindField;	ldy #p_updateDraw	Set the wContDraw field.	ldx #wContDraw+2	jsr setWindField;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = =; 2        Initialize window's StructRgn and ContentRgn.;300= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = =;;   IN:    <w_wind = window pointer.;          <globals	= pointer to Window	Manager's global data area.;;  OUT:    <w_wrect =	trashed.;alertRgns	jsr getGlobalRect	w_wrect = port bounds.;;; --- Compute content region ---------------------------------;	ldy #wcontRgn+2	Pass handle of content region.	jsr pushWindLong	jsr pushwrect	_RectRgn;;; --- Compute size of frame by expanding the content area ----;	jsr pushwrect	Common need.;	ldx #-8	Width of vertical frame in 320 mode.	ldy #screenMode	lda [<globals],y	beq store300	ldx #-12store300	phx	pea $FFFB	Horizontal frame height.	_InsetRect;	ldy #wstrucRgn+2	Pass handle of StructRgn.	jsr pushWindLong	jsr pushwrect	Set to global RECT in 'w_wrect'.	_RectRgn;	clc	No error.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = = =; 5        Return address of routine to	draw window outline.;510= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = = = =;;  OUT:    x/a = result, zero for default outline.;alertDrag		; ;;; = = = = = = = = =	= = = = = = = = = =	= = = = =; 6        Draw grow window outline.;600= = = = = = = =	= = = = = = = = = =	= = = = =;;  OUT:    x/a = result.;alertGrow		; ;	lda #0	Perform default action.	tax	clc	No error.	rts;	ENDP;;;            APPEND	DEFUTIL.ASM	TITLE 'Apple IIGS Window Manager                   DEFUTIL.ASM';;          Copyright Apple Computer, Inc. 1986-1987;          All rights reserved;          Written by Dan Oliver;;        This module contains routines common to standard window defProcs.;;;=====================================;        Get a region's bounds.;=====================================;;   IN:    <w_wind = window record that contain region handle.;          y = index into window for region handle.;;  OUT:    <w_wrect =	bounds of region.;getRgnBounds	PROC;		;using equates;	lda [<w_wind],y	Get handle from window record.	tax	iny	iny	lda [<w_wind],y	bra enter1;;; = = = = = = = = =	= = = = = = = = = =	= =;          Get bounds of desktop.;100= = = = = = = =	= = = = = = = = = =	= =;	ENTRY getDeskBoundsgetDeskBounds		;       ;	pha	Space for result.	pha	pea 2	Pass 'get desktop region' command.	pha	Pass parameter (not	used).	pha	_Desktop	plx	Get handle of desktop region.	pla;enter1	pei <w_work+2	Save.	pei <w_work;	stx <w_work	sta <w_work+2;	ldy #2	lda [<w_work],y	tay	lda [<w_work]	clc	adc #Rgn_Bounds	I'm after the region's bounds.	bcc store1	inystore1	sta <w_work	sty <w_work+2	That's the pointer to bounds.;	ldy #x2	Put bounds into 'w_wrect'.lop1	tyx	lda [<w_work],y	sta <w_wrect,x	dey	dey	bpl lop1;	pla	Restore.	sta <w_work	pla	sta <w_work+2;	rts	ENDP;;;===================================================;        Push address of direct page location.;===================================================;pushwrect	PROC	lda #w_wrect	bra ok1;	ENTRY pushParampushParam		;       	lda #w_param	bra ok1;	ENTRY pushrectpushrect		;       	lda #w_rectok1	brl pushDpage	ENDP;;;==============================================;        Push a long from window record.;==============================================;;   IN:    y = offset into window record.;          <w_wind = pointer to window record.;pushWindLong	PROC;		;using equates;	plx	Get return address.;	lda [<w_wind],y	Put long on stack.	pha	dey	dey	lda [<w_wind],y	pha;	phx	Put return address back on stack.	rts	ENDP;;;========================================;        Move 'w_wrect' into 'w_rect';========================================;;   IN:    <w_wrect = RECT to clone.;;  OUT:    <w_rect = clone of <w_wrect.;cloneRect	PROC;		;using equates;	ldx #x2lop	lda <w_wrect,x	sta <w_rect,x	dex	dex	bpl lop	rts	ENDP;;;====================================================;          Set window's color table pointer.;====================================================;;   IN:    w_wind = pointer to window.;;  OUT:    <windColors = pointer to color table.;setcolorptr	PROC;	ldy #wcolor	Fetch color table field from window record.	lda [<w_wind],y	tax	iny	iny	lda [<w_wind],y	bmi @handle	Is the color table a handle?	bne @store1	Is the color table a pointer?	txy	bne @store1;;; --- NIL color table, use default.;	ldy #defWindClr	Use default color table.	lda [<globals],y	tax	iny	iny	lda [<globals],y	bpl @store1	Is default a pointer?;;; --- Handle for color table.;@handle	stx <windColors	Store handle.	sta <windColors+2;	ldy #4	Lock the color table.	lda [<windColors],y	ora #$8000	sta [<windColors],y	dey	Dereference the color table.	dey	lda [<windColors],y	pha	lda [<windColors]	tax	pla;@store1	stx <windColors	sta <windColors+2	rts	ENDP;;;====================================================;          Unlock window's color table.;====================================================;;   IN:    <w_wind = pointer to window.;;  OUT:    Color table unlocked if it is a handle.  This includes the default table.;unlockColor	PROC;	ldy #wcolor	Fetch color table field from window record.	lda [<w_wind],y	tax	iny	iny	lda [<w_wind],y	bmi @handle	Is the color table a handle?	bne @exit	Is the color table a pointer?	txy	bne @exit	If a pointer, nothing to unclock.;;; --- NIL color table, unlock default.;	ldy #defWindClr	Use default color table.	lda [<globals],y	tax	iny	iny	lda [<globals],y	bpl @exit	Is default a pointer?  If yes, nothing to unlock.;;; --- Handle for color table.;@handle	pei <w_work+2	Save.	pei <w_work;*****	sta <w_work	Store handle.	***** This is how it is in ROM 3.  --DAL 14-Nov-90*****	stx <w_work+2		***** The two words are interchanged.	sta <w_work+2	;fixed 14-Nov-90 DAL	stx <w_work	;fixed 14-Nov-90 DAL;	ldy #4	Unlock the color table.	lda [<w_work],y	and #$7FFF	sta [<w_work],y;	pla	Restore.	sta <w_work	pla	sta <w_work+2;@exit	rts	ENDP;;;================================================;        Set pen to	a pattern and color.;================================================;;   IN:    y = offset into color table to get pattern/color.;          <w_wind = pointer to window.;          <windColors = pointer to color table.;	EXPORT setoutlinesetoutline	PROC	lda [<windColors],y	and #$00F0	Solid color for line only.	asl a	clc***	adc #colorBlack	Compute address of solid color.	export SelfMod2LowSelfMod2Low	adc #$7777	;27-Sep-90 DAL***	pea colorBlack>>16	Pass pointer to pattern.	export SelfMod2HighSelfMod2High	pea $7777	;27-Sep-90 DAL	pha	_SetPenPat	Set Pen Pattern.	rts	ENDP;==================================;          Frame a RECT.;==================================;;  IN:     <w_rect = RECT to draw and frame.;          Pen set to pattern.;framerect	PROC;	jsr pushrect	Pass address of 'w_rect'.	_FrameRect	rts	ENDP;;;=================================================;          Push pointer to current port.;=================================================;;   IN:    Nothing.;;  OUT:    PUSH:LONG - pointer to current port.;pushPort	PROC;	pha	Space for result.	pha	_GetPort	Get current port.	pla	plx;	ply	Get return address.;	phx	Push current port.	pha;	phy	Put return address back.	rts	ENDP;;;================================;          Push line size.;================================;;   IN:    <globals	= pointer to Window	Manager's global data area.;;  OUT:    PUSH:WORD - width of lines.;          PUSH:WORD - height of lines.;pushLineSize	PROC	jsr getLineSize	a = width, x = height.;	ply	Get return address.;	pha	Push width.	phx	Push height.;	phy	Put return address back.	rts	ENDP;;;===================================;          Get size	of lines.;===================================;;   IN:    <globals	= pointer to Window	Manager's global data area.;;  OUT:    a = width of lines.;          x = height of lines.;getLineSize	PROC	ldy #lineW	lda [<globals],y	Return width in a.	ldx #1	Return height in x.	rts	ENDP;;;====================================================;          Get bounds of window's strucRgn.;====================================================;;   IN:    <w_wind = pointer to window.;;  OUT:    <w_wrect =	bounds of window's strucRgn in local.;          <w_rect = bounds of window's strucRgn in local.;          <w_work = trash.;getLocalRect	PROC	ldy #wStrucRgn	Fetch window's strucRgn handle.	jsr getRgnBounds	<w_wrect = bounds of strucRgn in global.	jsr cloneRect	<w_rect = <w_wrect.;;; = = = = = = = = =	= = = = = = = = = =	= =;          Convert <w_wrect to local.;100= = = = = = = =	= = = = = = = = = =	= =;;   IN:    <w_wrect = RECT.;;  OUT:    <w_wrect =	local (where y1,x1 are now 0,0);          <w_rect = clone of <w_wrect.;	ENTRY makeRectLocalmakeRectLocal		;       ;	ldx #x1lop100	lda <w_rect+y2,x	sec	sbc <w_rect+y1,x	sta <w_rect+y2,x	sta <w_wrect+y2,x	stz <w_rect+y1,x	stz <w_wrect+y1,x	dex	dex	bpl lop100;	rts	ENDP;;;==========================================================;          Get global coordinates of window port.;==========================================================;;   IN:    w_wind = pointer to window record.;;  OUT:    w_wrect = RECT of window grafPort in global.;getGlobalRect	PROC	ldy #wport+GP_PortRect+y1	lda [<w_wind],y	ldy #wport+boundsRect+y1	sec	sbc [<w_wind],y	sta <w_wrect+y1;	ldy #wport+GP_PortRect+x1	lda [<w_wind],y	ldy #wport+boundsRect+x1	sec	sbc [<w_wind],y	sta <w_wrect+x1;	ldy #wport+GP_PortRect+y2	lda [<w_wind],y	ldy #wport+boundsRect+y1	sec	sbc [<w_wind],y	sta <w_wrect+y2;	ldy #wport+GP_PortRect+x2	lda [<w_wind],y	ldy #wport+boundsRect+x1	sec	sbc [<w_wind],y	sta <w_wrect+x2;	rts	ENDP;;;=================================================================;          Allocate	a stack based direct page for defProc.;=================================================================;startup	PROC	plx	Get return address.;	phd	Save caller's direct page.;	tsc	Allocate direct page.	sec	sbc #DIRECTSIZE	tcs	tcd;	phx	Put return address back on stack.	rts	ENDP;;;==============================================================;          Strip input parameters and exit defProc call.;==============================================================;shutdown	PROC	ldx <saveDpage;	lda <returnAddr+1	sta <returnAddr+15	lda <returnAddr	sta <returnAddr+14;	tsc	clc	adc #DIRECTSIZE+16	tcs;	txa	Restore caller's direct page pointer.	tcd;	tya	Return error code in A.	cmp #1	Set carry if error.	rtl	ENDP;;;=====================================================================;	Push pointer to window's title.;=====================================================================;;   IN: <w_wind = pointer to window.;;  OUT: Window title pointer on stack, handle locked.;       Call unlockTitle when done.;pushWindTitle	PROC;	ldy #wTitle+2	Is title a handle?	lda [<w_wind],y	bpl @justPush;	pei <w_work+2	Save.	pei <w_work;	sta <w_work+2	dey	dey	lda [<w_wind],y	sta <w_work;	ldy #4	Lock the title.	lda [<w_work],y	ora #$8000	sta [<w_work],y	dey	Get title pointer.	dey	lda [<w_work],y	tay	lda [<w_work];	plx	Restore.	stx <w_work	plx	stx <w_work+2	plx	Get return address.	phy	Push title pointer on stack.	pha	phx	Put return address back.	rts;@justPush	brl pushWindLong	Push title pointer directly from window record.	ENDP;;;================================================================;	Unlock window title handle.;================================================================;;   IN: <w_wind = pointer to window.;;  OUT: Window title handle unlocked if it is a handle.;unlockTitle	PROC;	ldy #wTitle+2	Is title a handle?	lda [<w_wind],y	bpl @exit;	pei <w_work+2	Save.	pei <w_work;	sta <w_work+2	dey	dey	lda [<w_wind],y	sta <w_work;	ldy #4	Unlock the title.	lda [<w_work],y	and #$7FFF	sta [<w_work],y;	plx	Restore.	stx <w_work	plx	stx <w_work+2@exit	rts	ENDP;	END